/**
 * Scene definitions for dance.goonify.fun.
 *
 * Each scene references a pre-rendered H4 dancer plate (a ping-pong webm that
 * loops seamlessly) and a keyframe track describing where the dancer's face
 * is in CANVAS pixel coords (1280×720) at evenly-spaced t values in [0..1].
 * `faceHoleAt(scene, t)` linearly interpolates between keyframes.
 *
 * Keyframes carry:
 *   - face bbox + rotation + head yaw (the legacy fields, used for the
 *     fallback oval-based draw)
 *   - `landmarks`: 478 MediaPipe FaceLandmarker landmarks in CANVAS pixel
 *     coords, used for Delaunay-based face warping (see lib/face/warp.ts)
 *
 * Keyframes are auto-measured by `pnpm measure-keyframes`, which spins up a
 * headless Chromium, runs MediaPipe FaceLandmarker against every keyframe of
 * every scene's webm, and extracts landmarks + yaw from the 4×4 facial
 * transformation matrix. Re-run that command after regenerating a plate;
 * the script writes `scripts/keyframes-measured.json` and prints a paste-
 * ready table.
 *
 * - The "front" plate is a slow vertical bob with a tiny horizontal sway.
 *   The dancer's face sits upper-centre; cx sways 655-711 and cy bobs
 *   206-235 over the loop, with consistent ~16-29° yaw.
 * - The "side" plate shows the dancer doing a 360° spin around the pole.
 *   Pose-spin-pose: yaw = 17 → 34 → 180 → 180 → 180 → 39 → 19. The patch
 *   fades out smoothly through the yaw=90° dead zone between k1 and k2,
 *   and fades back in between k4 and k5.
 */

export type FaceLandmark = { x: number; y: number }

export type FaceHoleKeyframe = {
  t: number
  cx: number
  cy: number
  rx: number
  ry: number
  rotation: number  // degrees; positive = clockwise
  /** Head yaw in degrees, 0 = facing camera, 90 = head turned 90° to camera's
   *  right (dancer's left if facing camera), 180 = back of head. Used to fade
   *  the face patch and squash it horizontally so it doesn't sit on the back
   *  of the dancer's head during a 360° spin. Linear interp between keyframes
   *  is fine — visibility is driven by `max(0, cos(yaw))` so the back-of-head
   *  dead zone is naturally wide enough. */
  headYaw: number
  /** 478-point face mesh in CANVAS pixel coords, used for Delaunay warping.
   *  Required for landmark-based face swap; keyframes without it fall back
   *  to the legacy oval-based path. */
  landmarks?: FaceLandmark[]
}

export type Scene = {
  id: string
  title: string
  dancer: string
  /** Keyframes evenly spaced across t ∈ [0..1]; first and last share values
   *  so the loop wraps invisibly. */
  track: FaceHoleKeyframe[]
}

// Canvas resolution — kept in sync with SceneCanvas.tsx and drawScene.ts.
export const CANVAS_W = 1280
export const CANVAS_H = 720

/**
 * Per-scene landmark counts (number of MediaPipe FaceLandmarker points).
 * Used by the interpolation to know how many landmarks to interpolate. The
 * keyframes store all 478 points; this constant is just for safety checks.
 */
export const LANDMARKS_PER_FACE = 478

