export function getScene(id: string): Scene | undefined {
  return SCENES.find((s) => s.id === id)
}

/**
 * Linearly interpolate between keyframes for the current video time t (0..1).
 * t=0 and t=1 share values, so the loop wraps invisibly.
 *
 * Landmarks interpolate alongside the rest of the keyframe, per-vertex:
 *   landmarks[i].x = a.landmarks[i].x + (b.landmarks[i].x - a.landmarks[i].x) * u
 * If either side of the interpolation has no `landmarks` field (e.g., the
 * mid-spin back-of-head keyframes typically don't), the interpolated result
 * also has no landmarks — the renderer falls back to the legacy oval path.
 */
export function faceHoleAt(scene: Scene, t: number): FaceHoleKeyframe {
  const k = scene.track
  if (k.length === 0) {
    return { t: 0, cx: CANVAS_W / 2, cy: CANVAS_H / 2, rx: 80, ry: 90, rotation: 0, headYaw: 0 }
  }
  if (k.length === 1 || t <= k[0].t) return k[0]
  if (t >= k[k.length - 1].t) return k[k.length - 1]

  for (let i = 0; i < k.length - 1; i++) {
    const a = k[i], b = k[i + 1]
    if (t >= a.t && t <= b.t) {
      const span = b.t - a.t
      const u = span === 0 ? 0 : (t - a.t) / span
      // Interpolate landmarks only if both sides have them with matching
      // point counts. Otherwise the interpolated keyframe has no landmarks
      // and the renderer falls back to the oval path.
      let landmarks: FaceLandmark[] | undefined
      if (a.landmarks && b.landmarks && a.landmarks.length === b.landmarks.length) {
        landmarks = new Array(a.landmarks.length)
        for (let j = 0; j < a.landmarks.length; j++) {
          landmarks[j] = {
            x: a.landmarks[j].x + (b.landmarks[j].x - a.landmarks[j].x) * u,
            y: a.landmarks[j].y + (b.landmarks[j].y - a.landmarks[j].y) * u,
          }
        }
      }
      return {
        t,
        cx: a.cx + (b.cx - a.cx) * u,
        cy: a.cy + (b.cy - a.cy) * u,
        rx: a.rx + (b.rx - a.rx) * u,
        ry: a.ry + (b.ry - a.ry) * u,
        rotation: a.rotation + (b.rotation - a.rotation) * u,
        headYaw: a.headYaw + (b.headYaw - a.headYaw) * u,
        landmarks,
      }
    }
  }
  return k[k.length - 1]
}
